-- Transferencias bancarias internas TRF_BAN.
alter table public.bank_transfer add column if not exists subsidiary_id bigint references public.subsidiaries(subsidiary_id),add column if not exists accreditation_date date,add column if not exists bank_confirmation text,add column if not exists concept text,add column if not exists source_amount numeric(24,6),add column if not exists destination_amount numeric(24,6),add column if not exists applied_exchange_rate numeric(24,10),add column if not exists source_base_rate numeric(24,10),add column if not exists destination_base_rate numeric(24,10),add column if not exists source_base_amount numeric(24,6),add column if not exists destination_base_amount numeric(24,6),add column if not exists fx_gain_loss numeric(24,6) not null default 0,add column if not exists commission_amount numeric(24,6) not null default 0,add column if not exists journal_id bigint references public.journal(journal_id),add column if not exists created_by bigint references public.users(user_id),add column if not exists status text not null default 'APROBADA',add column if not exists created_at timestamptz not null default now();
update public.bank_transfer bt set subsidiary_id=ba.subsidiary_id,accreditation_date=coalesce(bt.accreditation_date,bt.transfer_date),source_amount=coalesce(bt.source_amount,bt.amount),destination_amount=coalesce(bt.destination_amount,bt.amount),applied_exchange_rate=coalesce(bt.applied_exchange_rate,1),source_base_rate=coalesce(bt.source_base_rate,1),destination_base_rate=coalesce(bt.destination_base_rate,1),source_base_amount=coalesce(bt.source_base_amount,bt.amount),destination_base_amount=coalesce(bt.destination_base_amount,bt.amount) from public.bank_account ba where ba.bank_account_id=bt.from_account_id;
alter table public.bank_transfer alter column subsidiary_id set not null,alter column accreditation_date set not null,alter column source_amount set not null,alter column destination_amount set not null,alter column applied_exchange_rate set not null,alter column source_base_rate set not null,alter column destination_base_rate set not null,alter column source_base_amount set not null,alter column destination_base_amount set not null;
alter table public.bank_transfer drop constraint if exists bank_transfer_status_allowed;alter table public.bank_transfer add constraint bank_transfer_status_allowed check(status in('APROBADA','ANULADA'));
alter table public.bank_transfer drop constraint if exists bank_transfer_amounts_positive;alter table public.bank_transfer add constraint bank_transfer_amounts_positive check(source_amount>0 and destination_amount>0 and applied_exchange_rate>0 and commission_amount>=0);
create index if not exists bank_transfer_analytics_idx on public.bank_transfer(subsidiary_id,from_account_id,to_account_id,transfer_date,status);
create index if not exists bank_transfer_search_idx on public.bank_transfer(subsidiary_id,bank_confirmation,transfer_number);
drop policy if exists banking_select on public.bank_transfer;drop policy if exists banking_insert on public.bank_transfer;drop policy if exists banking_update on public.bank_transfer;drop policy if exists banking_delete on public.bank_transfer;drop policy if exists bank_transfer_company_access on public.bank_transfer;
create policy bank_transfer_company_access on public.bank_transfer for select to authenticated using(subsidiary_id=public.active_subsidiary_id());

create or replace function public.bank_transfer_options() returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('subsidiaryId',s.subsidiary_id,'baseCurrencyId',s.currency_id,'baseCurrencyCode',bc.currency_code,'accounts',coalesce((select jsonb_agg(jsonb_build_object('id',ba.bank_account_id,'number',ba.account_number,'name',b.bank_name||' · '||ba.account_number||' · '||c.currency_code,'bank',b.bank_name,'currencyId',ba.currency_id,'currencyCode',c.currency_code,'currencySymbol',c.symbol,'balance',ba.balance,'ledgerAccountId',ba.account_id) order by b.bank_name,ba.account_number) from bank_account ba join banks b using(bank_id) join currencies c using(currency_id) where ba.subsidiary_id=s.subsidiary_id and coalesce(ba.is_credit_card,false)=false),'[]'::jsonb),'rates',coalesce((select jsonb_agg(jsonb_build_object('fromCurrencyId',from_currency_id,'toCurrencyId',to_currency_id,'date',effective_date,'rate',spot_rate) order by effective_date desc) from exchange_rates where effective_date<=current_date),'[]'::jsonb),'currencies',(select coalesce(jsonb_agg(jsonb_build_object('id',currency_id,'code',currency_code,'symbol',symbol)),'[]'::jsonb) from currencies),'commissionAccounts',coalesce((select jsonb_agg(jsonb_build_object('id',ca.account_id,'number',ca.account_number,'name',ca.account_name) order by ca.account_number) from chart_accounts ca join account_subsidiaries aus using(account_id) where aus.subsidiary_id=s.subsidiary_id and aus.is_active and not ca.is_inactive and not ca.is_summary and (lower(ca.account_name) like '%comisi%' or lower(ca.account_name) like '%gasto banc%')),'[]'::jsonb)) from subsidiaries s join currencies bc on bc.currency_id=s.currency_id where s.subsidiary_id=public.active_subsidiary_id()$$;

create or replace function public.create_bank_transfer(p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare sid bigint:=active_subsidiary_id();uid bigint:=app_user_id();src bank_account%rowtype;dst bank_account%rowtype;d date:=(p_payload->>'transferDate')::date;ad date:=coalesce(nullif(p_payload->>'accreditationDate','')::date,d);sa numeric:=(p_payload->>'sourceAmount')::numeric;da numeric:=(p_payload->>'destinationAmount')::numeric;fee numeric:=coalesce(nullif(p_payload->>'commissionAmount','')::numeric,0);sr numeric;dr numeric;applied numeric;sb numeric;db numeric;fx numeric;tt bigint;status_key bigint;fp bigint;base_currency bigint;num text;tid bigint;jid bigint;trid bigint;fx_account bigint;fee_account bigint;
begin
 if sid is null then raise exception 'Seleccione una subsidiaria antes de transferir.';end if;if d is null or ad is null then raise exception 'Las fechas de emisión y acreditación son obligatorias.';end if;if ad<d then raise exception 'La fecha de acreditación no puede ser anterior a la emisión.';end if;if sa<=0 or da<=0 or fee<0 then raise exception 'Los montos deben ser positivos.';end if;
 select * into src from bank_account where bank_account_id=(p_payload->>'sourceAccountId')::bigint for update;select * into dst from bank_account where bank_account_id=(p_payload->>'destinationAccountId')::bigint for update;
 if src.bank_account_id is null or dst.bank_account_id is null then raise exception 'Seleccione cuentas bancarias válidas.';end if;if src.bank_account_id=dst.bank_account_id then raise exception 'Las cuentas deben ser diferentes.';end if;if src.subsidiary_id<>sid or dst.subsidiary_id<>sid then raise exception 'Ambas cuentas deben pertenecer a la subsidiaria activa.';end if;if src.balance<sa+fee then raise exception 'Saldo insuficiente: disponible %, requerido %.',round(src.balance,2),round(sa+fee,2);end if;if src.currency_id=dst.currency_id and abs(sa-da)>.005 then raise exception 'En la misma moneda ambos montos deben ser iguales.';end if;
 select currency_id into base_currency from subsidiaries where subsidiary_id=sid;sr:=case when src.currency_id=base_currency then 1 else coalesce((select spot_rate from exchange_rates where from_currency_id=src.currency_id and to_currency_id=base_currency and effective_date<=d order by effective_date desc limit 1),(select 1/spot_rate from exchange_rates where from_currency_id=base_currency and to_currency_id=src.currency_id and effective_date<=d order by effective_date desc limit 1)) end;dr:=case when dst.currency_id=base_currency then 1 else coalesce((select spot_rate from exchange_rates where from_currency_id=dst.currency_id and to_currency_id=base_currency and effective_date<=d order by effective_date desc limit 1),(select 1/spot_rate from exchange_rates where from_currency_id=base_currency and to_currency_id=dst.currency_id and effective_date<=d order by effective_date desc limit 1)) end;if sr is null or dr is null then raise exception 'No existe tipo de cambio a moneda base para la fecha.';end if;
 applied:=case when src.currency_id=base_currency and dst.currency_id=base_currency then 1 when src.currency_id=dst.currency_id then sr when src.currency_id=base_currency then sa/da when dst.currency_id=base_currency then da/sa else sr end;sb:=round(sa*sr,6);db:=round(da*dr,6);fx:=round(db-sb,6);select transaction_type_id into tt from transaction_types where abbreviation='TRF_BAN' limit 1;select status_id into status_key from status where code='APROBADO' and module='Transacciones' limit 1;select fiscal_period_id into fp from fiscal_periods where subsidiary_id=sid and d between start_date and end_date and not is_closed limit 1;if tt is null or status_key is null then raise exception 'Configure TRF_BAN y el estado APROBADO.';end if;if fp is null then raise exception 'No existe un período contable abierto para la fecha.';end if;
 begin num:=next_transaction_number(tt,sid);exception when others then num:='TRF_BAN-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS');end;insert into "transaction"(tran_number,tran_date,transaction_type_id,subsidiary_id,currency_id,exchange_rate,fiscal_period_id,total_amount,status_id) values(num,d,tt,sid,src.currency_id,sr,fp,sb,status_key) returning transaction_id into tid;insert into journal(journal_number,journal_date,transaction_id,subsidiary_id,currency_id,fiscal_period_id,exchange_rate,memo,journal_type,total_debit,total_credit,status) values(num,d,tid,sid,base_currency,fp,1,coalesce(nullif(p_payload->>'concept',''),'Transferencia entre cuentas'),'Transferencia bancaria',db+greatest(-fx,0)+fee*sr,sb+greatest(fx,0)+fee*sr,'CONTABILIZADO') returning journal_id into jid;
 insert into journal_line(journal_id,account_id,debit,credit,debit_fx,credit_fx,note) values(jid,dst.account_id,da,0,db,0,'Entrada '||num),(jid,src.account_id,0,sa+fee,0,sb+fee*sr,'Salida '||num);
 if fee>0 then fee_account:=nullif(p_payload->>'commissionAccountId','')::bigint;if fee_account is null then raise exception 'Seleccione la cuenta contable de comisión.';end if;insert into journal_line(journal_id,account_id,debit,credit,debit_fx,credit_fx,note) values(jid,fee_account,fee,0,fee*sr,0,'Comisión bancaria '||num);end if;
 if abs(fx)>.005 then select ca.account_id into fx_account from chart_accounts ca join account_subsidiaries aus using(account_id) where aus.subsidiary_id=sid and aus.is_active and not ca.is_inactive and not ca.is_summary and (lower(ca.account_name) like '%cambi%' or lower(ca.account_name) like '%exchange%') order by case when fx>0 and lower(ca.account_name) like '%ganan%' then 0 when fx<0 and lower(ca.account_name) like '%pérd%' then 0 else 1 end limit 1;if fx_account is null then raise exception 'Configure una cuenta de ganancia/pérdida cambiaria.';end if;insert into journal_line(journal_id,account_id,debit,credit,debit_fx,credit_fx,note) values(jid,fx_account,case when fx<0 then abs(fx) else 0 end,case when fx>0 then fx else 0 end,case when fx<0 then abs(fx) else 0 end,case when fx>0 then fx else 0 end,'Diferencial cambiario '||num);end if;
 insert into bank_transfer(transfer_number,from_account_id,to_account_id,transaction_id,amount,transfer_date,subsidiary_id,accreditation_date,bank_confirmation,concept,source_amount,destination_amount,applied_exchange_rate,source_base_rate,destination_base_rate,source_base_amount,destination_base_amount,fx_gain_loss,commission_amount,journal_id,created_by,status) values(num,src.bank_account_id,dst.bank_account_id,tid,sa,d,sid,ad,nullif(p_payload->>'bankConfirmation',''),nullif(p_payload->>'concept',''),sa,da,applied,sr,dr,sb,db,fx,fee,jid,uid,'APROBADA') returning transfer_id into trid;
 insert into bank_transaction(tran_date,value_date,bank_account_id,transaction_id,amount,tran_type,reference_number,description,reconciliation_status) values(d,ad,src.bank_account_id,tid,-(sa+fee),'TRF_BAN',coalesce(nullif(p_payload->>'bankConfirmation',''),num),coalesce(nullif(p_payload->>'concept',''),'Transferencia saliente'),'PENDIENTE_EN_TRANSITO'),(d,ad,dst.bank_account_id,tid,da,'TRF_BAN',coalesce(nullif(p_payload->>'bankConfirmation',''),num),coalesce(nullif(p_payload->>'concept',''),'Transferencia entrante'),'PENDIENTE_EN_TRANSITO');update bank_account set balance=balance-sa-fee where bank_account_id=src.bank_account_id;update bank_account set balance=balance+da where bank_account_id=dst.bank_account_id;return jsonb_build_object('transferId',trid,'transactionNumber',num,'journalId',jid);
end$$;

create or replace function public.run_bank_transfer_report(p_filters jsonb default '{}'::jsonb) returns jsonb language plpgsql stable security definer set search_path=public as $$declare sid bigint:=active_subsidiary_id();df date:=nullif(p_filters->>'dateFrom','')::date;dt date:=nullif(p_filters->>'dateTo','')::date;view_mode text:=coalesce(p_filters->>'currencyView','TRANSACTIONAL');q text:=lower(coalesce(p_filters->>'search',''));src_ids bigint[];dst_ids bigint[];result jsonb;begin if df is null or dt is null then raise exception 'El rango de fechas es obligatorio.';end if;if df>dt then raise exception 'El rango de fechas no es válido.';end if;select array_agg(value::bigint) into src_ids from jsonb_array_elements_text(coalesce(p_filters->'sourceAccountIds','[]'::jsonb));select array_agg(value::bigint) into dst_ids from jsonb_array_elements_text(coalesce(p_filters->'destinationAccountIds','[]'::jsonb));with report_rows as(select bt.transfer_id,bt.transfer_date,bt.accreditation_date,bt.transfer_number,bt.bank_confirmation,bt.concept,bt.from_account_id,bt.to_account_id,bs.bank_name||' · '||sa.account_number||' · '||sc.currency_code source_account,bd.bank_name||' · '||da.account_number||' · '||dc.currency_code destination_account,sc.currency_code source_currency,dc.currency_code destination_currency,case when view_mode='BASE' then bt.source_base_amount else bt.source_amount end source_amount,case when view_mode='BASE' then bt.destination_base_amount else bt.destination_amount end destination_amount,bt.applied_exchange_rate,bt.fx_gain_loss,bt.journal_id,coalesce(u.first_name||' '||u.last_name,u.email,'—') processed_by,bt.source_base_amount from bank_transfer bt join bank_account sa on sa.bank_account_id=bt.from_account_id join banks bs on bs.bank_id=sa.bank_id join currencies sc on sc.currency_id=sa.currency_id join bank_account da on da.bank_account_id=bt.to_account_id join banks bd on bd.bank_id=da.bank_id join currencies dc on dc.currency_id=da.currency_id left join users u on u.user_id=bt.created_by where bt.subsidiary_id=sid and bt.status='APROBADA' and bt.transfer_date between df and dt and (src_ids is null or bt.from_account_id=any(src_ids)) and (dst_ids is null or bt.to_account_id=any(dst_ids)) and (q='' or lower(coalesce(bt.transfer_number,'')||' '||coalesce(bt.bank_confirmation,'')||' '||coalesce(bt.concept,'')) like '%'||q||'%')) select jsonb_build_object('rows',coalesce(jsonb_agg(to_jsonb(report_rows)-'source_base_amount' order by transfer_date desc,transfer_id desc),'[]'::jsonb),'summary',jsonb_build_object('totalTransferred',coalesce(sum(source_base_amount),0),'fxGainLoss',coalesce(sum(fx_gain_loss),0)),'currencyView',view_mode) into result from report_rows;return result;end$$;
create or replace function public.bank_transfer_journal(p_transfer_id bigint) returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('journalId',j.journal_id,'number',j.journal_number,'date',j.journal_date,'memo',j.memo,'status',j.status,'lines',coalesce((select jsonb_agg(jsonb_build_object('accountNumber',ca.account_number,'accountName',ca.account_name,'debit',jl.debit,'credit',jl.credit,'debitBase',jl.debit_fx,'creditBase',jl.credit_fx,'note',jl.note) order by jl.journal_line_id) from journal_line jl join chart_accounts ca using(account_id) where jl.journal_id=j.journal_id),'[]'::jsonb)) from bank_transfer bt join journal j on j.journal_id=bt.journal_id where bt.transfer_id=p_transfer_id and bt.subsidiary_id=active_subsidiary_id()$$;
revoke all on function public.bank_transfer_options() from public,anon;revoke all on function public.create_bank_transfer(jsonb) from public,anon;revoke all on function public.run_bank_transfer_report(jsonb) from public,anon;revoke all on function public.bank_transfer_journal(bigint) from public,anon;grant execute on function public.bank_transfer_options(),public.create_bank_transfer(jsonb),public.run_bank_transfer_report(jsonb),public.bank_transfer_journal(bigint) to authenticated;
